<script setup>import {computed} from 'vue';const p=defineProps({value:Number});const c=2*Math.PI*50;const dash=computed(()=>Math.min(p.value||0,100)/100*c)</script><template><div class="ring-wrap"><svg viewBox="0 0 120 120"><circle class="ring-bg" cx="60" cy="60" r="50"/><circle class="ring-progress" cx="60" cy="60" r="50" :stroke-dasharray="`${dash} ${c}`"/></svg><div class="ring-label"><strong>{{(value||0).toFixed(1)}}%</strong><span>tercapai</span></div></div></template>